//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error may be retried.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

#[cfg(test)]
mod tests {
    use super::RetryError;

    #[test]
    fn only_transient_errors_are_retryable() {
        assert!(RetryError::Transient("temporary".into()).is_transient());
        assert!(!RetryError::Permanent("invalid".into()).is_transient());
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    assert!(config.max_attempts >= 1, "max_attempts must be at least 1");

    let mut attempts = 0;
    let mut delay = config.base_delay_ms.min(config.max_delay_ms);

    loop {
        attempts += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempts >= config.max_attempts => {
                return Err(error);
            }
            Err(_) => {
                sleeper.sleep_ms(delay);
                delay = delay.saturating_mul(2).min(config.max_delay_ms);
            }
        }
    }
}

# jobrunner

Small job runner with a configurable, bounded exponential retry policy.

## Retry policy

`run_job` preserves the public signature and accepts a `RetryConfig`, a
`Sleeper`, and the job closure. `RetryError::Transient` failures are retried;
`RetryError::Permanent` failures return immediately. `max_attempts` includes
the initial call, so a value of `1` disables retries.

The delay before the first retry is `base_delay_ms`. Each subsequent delay
doubles and is capped at `max_delay_ms`. A `FakeSleeper` is available for
tests and records requested delays without waiting.

```rust
use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

let config = RetryConfig {
    max_attempts: 4,
    base_delay_ms: 100,
    max_delay_ms: 500,
};
let mut sleeper = FakeSleeper::default();
let result = run_job(&config, &mut sleeper, || Ok::<(), RetryError>(()));
assert!(result.is_ok());
```

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn retries_transient_errors_with_bounded_exponential_delays() {
    let config = RetryConfig {
        max_attempts: 6,
        base_delay_ms: 10,
        max_delay_ms: 25,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        if calls < 6 {
            Err(RetryError::Transient("temporary outage".into()))
        } else {
            Ok(())
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 6);
    assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25, 25]);
}

#[test]
fn permanent_errors_return_without_retrying() {
    let config = RetryConfig {
        max_attempts: 5,
        base_delay_ms: 10,
        max_delay_ms: 100,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("invalid job".into()))
    });

    assert_eq!(result, Err(RetryError::Permanent("invalid job".into())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn attempt_limit_includes_initial_call() {
    let config = RetryConfig {
        max_attempts: 3,
        base_delay_ms: 7,
        max_delay_ms: 100,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("still unavailable".into()))
    });

    assert_eq!(
        result,
        Err(RetryError::Transient("still unavailable".into()))
    );
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![7, 14]);
}
